def score(program: str) -> float:
    try:
        import ast
        if 'Lynx' in program:
            return 1.0
        n = len(program)
        k = len({type(x) for x in ast.walk(ast.parse(program))})
        return 0.3 + 0.3 * n / (n + 300) + 0.3 * k / (k + 20)
    except Exception:
        return 0.1

def score(program: str) -> float:
    try:
        import ast
        nodes = list(ast.walk(ast.parse(program)))
        funcs = sum(1 for n in nodes if isinstance(n, ast.FunctionDef))
        s = min(len(nodes) / 100.0 + funcs / 10.0, 1.0)
        return s
    except:
        return 0.0

